import java.util.Scanner;

public class SimpleCalculator {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Write your program here
        System.out.println("Give the first number:");
        int first = Integer.valueOf(scanner.nextLine());

        System.out.println("Give the second number:");
        int second = Integer.valueOf(scanner.nextLine());

        int sumOfNum = first + second;
        int subsOfNum = first - second;
        int multiOfNum = first * second;
        double deviOfNum = (double)first / second;


        System.out.println(first + " + " + second + " = " + sumOfNum);
        System.out.println(first + " - " + second + " = " + subsOfNum);
        System.out.println(first + " * " + second + " = " + multiOfNum);
        System.out.println(first + " / " + second + " = " + deviOfNum);

    }
}
